import Database from "better-sqlite3";

/**
 * Live overlay reader for the cognition graph.
 *
 * The cognition graph's *structure* is generated by the CLI
 * (/generated/cognition-graph.json). This reader supplies the *live* layer:
 * how much audit + event + HITL activity each module has actually seen, read
 * straight from the runtime's SQLite database.
 *
 * It opens its own read-only-style connection (like the state store does) and
 * is deliberately tolerant — if the runtime has never executed anything, the
 * tables may not exist yet, and every query simply returns zero.
 */

export interface ModuleActivity {
  events: number;
  auditRows: number;
  dryRunCount: number;
  pendingApprovals: number;
  lastActivity?: string;
}

export interface CognitionLiveOverlay {
  generatedAt: string;
  totals: {
    auditRows: number;
    events: number;
    pendingApprovals: number;
    snapshots: number;
    traces: number;
  };
  perModule: Record<string, ModuleActivity>;
  recentEvents: Array<{
    type: string;
    entity: string;
    occurredAt: string;
    sourceModule?: string;
    traceId?: string;
  }>;
  recentTraces: Array<{
    traceId: string;
    startedAt: string;
    workflow?: string;
    module?: string;
  }>;
}

export class CognitionLiveReader {
  private readonly db: Database.Database;

  constructor(filePath: string) {
    this.db = new Database(filePath);
    this.db.pragma("journal_mode = WAL");
  }

  /** Run a query, returning the fallback if the table does not exist yet. */
  private safe<T>(fn: () => T, fallback: T): T {
    try {
      return fn();
    } catch {
      return fallback;
    }
  }

  overlay(): CognitionLiveOverlay {
    const totals = {
      auditRows: this.safe(
        () => (this.db.prepare(`SELECT COUNT(*) n FROM audit_records`).get() as any).n,
        0,
      ),
      events: this.safe(
        () => (this.db.prepare(`SELECT COUNT(*) n FROM typed_events`).get() as any).n,
        0,
      ),
      pendingApprovals: this.safe(
        () =>
          (
            this.db
              .prepare(`SELECT COUNT(*) n FROM hitl_pending WHERE status = 'pending'`)
              .get() as any
          ).n,
        0,
      ),
      snapshots: this.safe(
        () => (this.db.prepare(`SELECT COUNT(*) n FROM state_snapshots`).get() as any).n,
        0,
      ),
      traces: this.safe(
        () =>
          (
            this.db
              .prepare(`SELECT COUNT(DISTINCT trace_id) n FROM audit_records WHERE trace_id IS NOT NULL`)
              .get() as any
          ).n,
        0,
      ),
    };

    const perModule: Record<string, ModuleActivity> = {};
    const touch = (mod: string): ModuleActivity => {
      if (!perModule[mod]) {
        perModule[mod] = { events: 0, auditRows: 0, dryRunCount: 0, pendingApprovals: 0 };
      }
      return perModule[mod];
    };

    // Audit rows per module.
    for (const r of this.safe(
      () =>
        this.db
          .prepare(
            `SELECT module, COUNT(*) n, SUM(dry_run) dry, MAX(started_at) last
             FROM audit_records WHERE module IS NOT NULL GROUP BY module`,
          )
          .all() as any[],
      [],
    )) {
      const m = touch(r.module);
      m.auditRows = r.n;
      m.dryRunCount = r.dry ?? 0;
      m.lastActivity = maxIso(m.lastActivity, r.last);
    }

    // Events per source module.
    for (const r of this.safe(
      () =>
        this.db
          .prepare(
            `SELECT source_module mod, COUNT(*) n, MAX(occurred_at) last
             FROM typed_events WHERE source_module IS NOT NULL GROUP BY source_module`,
          )
          .all() as any[],
      [],
    )) {
      const m = touch(r.mod);
      m.events = r.n;
      m.lastActivity = maxIso(m.lastActivity, r.last);
    }

    // Pending HITL approvals per module.
    for (const r of this.safe(
      () =>
        this.db
          .prepare(
            `SELECT module, COUNT(*) n FROM hitl_pending
             WHERE status = 'pending' AND module IS NOT NULL GROUP BY module`,
          )
          .all() as any[],
      [],
    )) {
      touch(r.module).pendingApprovals = r.n;
    }

    const recentEvents = this.safe(
      () =>
        (
          this.db
            .prepare(
              `SELECT type, entity_canonical_id entity, occurred_at, source_module, trace_id
               FROM typed_events ORDER BY occurred_at DESC LIMIT 20`,
            )
            .all() as any[]
        ).map((r) => ({
          type: r.type,
          entity: r.entity,
          occurredAt: r.occurred_at,
          sourceModule: r.source_module ?? undefined,
          traceId: r.trace_id ?? undefined,
        })),
      [],
    );

    const recentTraces = this.safe(
      () =>
        (
          this.db
            .prepare(
              `SELECT trace_id, MIN(started_at) started_at, workflow, module
               FROM audit_records WHERE trace_id IS NOT NULL
               GROUP BY trace_id ORDER BY started_at DESC LIMIT 10`,
            )
            .all() as any[]
        ).map((r) => ({
          traceId: r.trace_id,
          startedAt: r.started_at,
          workflow: r.workflow ?? undefined,
          module: r.module ?? undefined,
        })),
      [],
    );

    return {
      generatedAt: new Date().toISOString(),
      totals,
      perModule,
      recentEvents,
      recentTraces,
    };
  }

  close(): void {
    this.db.close();
  }
}

function maxIso(a: string | undefined, b: string | undefined): string | undefined {
  if (!a) return b ?? undefined;
  if (!b) return a;
  return a > b ? a : b;
}
